#' Standardized Incidence / Mortality Ratio (SIR / SMR)
#'
#' Computes standardized incidence ratios (SIR) or standardized mortality 
#' ratios (SMR) by indirect standardization. For each stratum the number of 
#' expected events is obtained by applying reference-population rates to the 
#' observed person-time; the SIR/SMR is the ratio of total observed to total 
#' expected events. Exact Poisson confidence intervals and a test against the 
#' null value of 1 are provided. This is the standard analysis for registry, 
#' cohort, and occupational studies comparing an observed event count with 
#' population expectation.
#' 
#'
#' @examples
#' \donttest{
#' # Long data: one row per stratum with observed events, person-time,
#' # and a reference rate (events per person-time unit).
#' standardizedratio(
#'     data = mydata,
#'     observed = "obs_events",
#'     personTime = "person_years",
#'     refRate = "reference_rate")
#'}
#' @param data The data as a data frame (one row per stratum).
#' @param inputMode Whether expected events are computed from a reference rate
#'   times person-time, or supplied directly as a column of expected counts.
#' @param observed Observed number of events in each stratum.
#' @param personTime Person-time at risk in each stratum (used when expected
#'   events are computed from a reference rate).
#' @param refRate Reference-population event rate for each stratum, expressed
#'   per person-time unit (used with inputMode = "rate").
#' @param expected Directly supplied expected events per stratum (used with
#'   inputMode = "expected").
#' @param stratum Optional stratum label used to report a per-stratum SIR/SMR
#'   table.
#' @param ratioType Whether to label results as a standardized incidence or
#'   mortality ratio.
#' @param conf_level Confidence level for the exact Poisson interval.
#' @param perStratum Report the SIR/SMR for each stratum in addition to the
#'   overall value.
#' @param showPlot Display a forest plot of the per-stratum and overall
#'   SIR/SMR.
#' @param showSummary Display a plain-language summary of the result.
#' @param showExplanation Display an explanation of indirect standardization.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$overallTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$stratumTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$explanation} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overallTable$asDF}
#'
#' \code{as.data.frame(results$overallTable)}
#'
#' @export
standardizedratio <- function(
    data,
    inputMode = "rate",
    observed,
    personTime = NULL,
    refRate = NULL,
    expected = NULL,
    stratum = NULL,
    ratioType = "sir",
    conf_level = 0.95,
    perStratum = TRUE,
    showPlot = TRUE,
    showSummary = FALSE,
    showExplanation = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("standardizedratio requires jmvcore to be installed (restart may be required)")

    if ( ! missing(observed)) observed <- jmvcore::resolveQuo(jmvcore::enquo(observed))
    if ( ! missing(personTime)) personTime <- jmvcore::resolveQuo(jmvcore::enquo(personTime))
    if ( ! missing(refRate)) refRate <- jmvcore::resolveQuo(jmvcore::enquo(refRate))
    if ( ! missing(expected)) expected <- jmvcore::resolveQuo(jmvcore::enquo(expected))
    if ( ! missing(stratum)) stratum <- jmvcore::resolveQuo(jmvcore::enquo(stratum))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(observed), observed, NULL),
            `if`( ! missing(personTime), personTime, NULL),
            `if`( ! missing(refRate), refRate, NULL),
            `if`( ! missing(expected), expected, NULL),
            `if`( ! missing(stratum), stratum, NULL))

    for (v in stratum) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- standardizedratioOptions$new(
        inputMode = inputMode,
        observed = observed,
        personTime = personTime,
        refRate = refRate,
        expected = expected,
        stratum = stratum,
        ratioType = ratioType,
        conf_level = conf_level,
        perStratum = perStratum,
        showPlot = showPlot,
        showSummary = showSummary,
        showExplanation = showExplanation)

    analysis <- standardizedratioClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

